#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31
#
# Tests for the #3835 vehicle: write-operator-permissions.mjs (the consent-gated
# operator-scope writer) and doctor's check-operator-permissions.sh. Fails on
# main, where neither file exists: the control for the whole PR.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
WRITER="$ROOT/src/skills/setup/scripts/write-operator-permissions.mjs"
CHECKER="$ROOT/src/skills/doctor/scripts/check-operator-permissions.sh"
PAYLOAD="$ROOT/src/skills/setup/references/operator-permissions.json"

PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); echo "  ok: $1"; }
bad() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }

T="$(mktemp -d "${TMPDIR:-/tmp}/op-perm-test.XXXXXX")"
trap 'rm -rf "$T"' EXIT

[ -f "$WRITER" ] && ok "writer exists" || bad "writer missing"
[ -f "$CHECKER" ] && ok "checker exists" || bad "checker missing"
[ -f "$PAYLOAD" ] && ok "payload exists" || bad "payload missing"
[ "$FAIL" -eq 0 ] || { echo "Results: $PASS passed, $FAIL failed"; exit 1; }

N_PAYLOAD="$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).deny.length)' "$PAYLOAD")"
[ "$N_PAYLOAD" -ge 30 ] && ok "payload carries $N_PAYLOAD deny rules" || bad "payload too small: $N_PAYLOAD"

S="$T/settings.json"

# 1. dry run writes nothing
node "$WRITER" --settings-path "$S" --dry-run --json > "$T/dry.json"
[ ! -e "$S" ] && ok "dry run creates no file" || bad "dry run wrote the target"
grep -q '"applied": false' "$T/dry.json" && ok "dry run reports applied:false" || bad "dry run applied flag wrong"

# 2. apply to a missing file creates it with the full payload
node "$WRITER" --settings-path "$S" --json > "$T/apply1.json"
N_WRITTEN="$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).permissions.deny.length)' "$S")"
[ "$N_WRITTEN" -eq "$N_PAYLOAD" ] && ok "fresh apply writes all $N_PAYLOAD rules" || bad "fresh apply wrote $N_WRITTEN"

# 3. idempotent: second apply adds nothing
node "$WRITER" --settings-path "$S" --json > "$T/apply2.json"
grep -q '"additions": \[\]' "$T/apply2.json" && ok "second apply is a no-op" || bad "second apply added rules"

# 4. union preserves user content and their own rules
node -e '
const fs=require("fs");
fs.writeFileSync(process.argv[1], JSON.stringify({model:"opus", permissions:{deny:["Bash(shutdown *)"], allow:["Read"]}}, null, 2));' "$T/user.json"
node "$WRITER" --settings-path "$T/user.json" --json > "$T/apply3.json"
node -e '
const s=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));
const ok = s.model==="opus" && s.permissions.allow[0]==="Read" && s.permissions.deny[0]==="Bash(shutdown *)";
process.exit(ok?0:1)' "$T/user.json" && ok "user keys, allow list and own deny order preserved" || bad "merge clobbered user content"

# 5. backup exists and rollback restores byte-identical content
BACKUP_COUNT="$(ls "$T"/user.json.ork-backup-* 2>/dev/null | wc -l | tr -d ' ')"
[ "$BACKUP_COUNT" -ge 1 ] && ok "backup created" || bad "no backup"
cp "$T/user.json" "$T/after-apply.json"
node "$WRITER" --settings-path "$T/user.json" --rollback > /dev/null
node -e '
const f=require("fs");
const rolled=JSON.parse(f.readFileSync(process.argv[1],"utf8"));
process.exit(Array.isArray(rolled.permissions.deny) && rolled.permissions.deny.length===1 ? 0 : 1)' "$T/user.json" \
  && ok "rollback restored the pre-apply file" || bad "rollback did not restore"

# 6. unparseable target: exit 2, untouched
printf '{broken' > "$T/broken.json"
RC=0; node "$WRITER" --settings-path "$T/broken.json" > /dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "unparseable target exits 2" || bad "unparseable target rc=$RC"
[ "$(cat "$T/broken.json")" = "{broken" ] && ok "unparseable target untouched" || bad "unparseable target modified"

# 7. checker: red on empty scopes, green after apply, sandbox reported
H="$T/home-red"; mkdir -p "$H/.claude"
RC=0; ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-red.json" || RC=$?
[ "$RC" -eq 1 ] && ok "checker exits 1 with no rules anywhere" || bad "checker red rc=$RC"
grep -q '"remedy":' "$T/check-red.json" && ok "checker names the remedy" || bad "no remedy in checker output"

node "$WRITER" --settings-path "$H/.claude/settings.json" --json > /dev/null
RC=0; ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-green.json" || RC=$?
[ "$RC" -eq 0 ] && ok "checker exits 0 after the writer ran" || bad "checker green rc=$RC"

# 8. sandbox posture surfaces
node -e '
const f=require("fs"); const p=process.argv[1];
const s=JSON.parse(f.readFileSync(p,"utf8"));
s.sandbox={enabled:true,network:{allowedDomains:["github.com"]}};
f.writeFileSync(p, JSON.stringify(s,null,2));' "$H/.claude/settings.json"
ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-sb.json" || true  # silent: known-noise
grep -q '"network": "allowlist"' "$T/check-sb.json" && ok "sandbox allowlist posture reported" || bad "sandbox posture missing"

# 9. #3877: a project-scope sandbox.enabled:false over a user scope that sets it true
#    is reported with the project file:line and the user file:line, never failed on.
H2="$T/home-sb"; mkdir -p "$H2/.claude"
printf '{\n  "sandbox": {\n    "enabled": true\n  }\n}\n' > "$H2/.claude/settings.json"
PJ="$T/proj-override"; mkdir -p "$PJ/.claude"
printf '{\n  "permissions": {},\n  "sandbox": {\n    "enabled": false\n  }\n}\n' > "$PJ/.claude/settings.local.json"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ" --json > "$T/check-ov.json" || true  # exit 1 expected: H2 carries no deny payload
node -e '
const o=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")); const ov=o.sandbox_override;
// mktemp can preserve a doubled slash from TMPDIR; the checker uses path.join.
const {normalize}=require("node:path");
const projectFile=normalize(process.argv[2]); const userFile=normalize(process.argv[3]);
const ok = ov && ov.file===projectFile && ov.line===4 && ov.user_file===userFile && ov.user_line===3
  && o.sandbox.enabled==="false" && o.sandbox.source===projectFile;
process.exit(ok?0:1)' "$T/check-ov.json" "$PJ/.claude/settings.local.json" "$H2/.claude/settings.json" \
  && ok "sandbox override names the project file:line and the user file:line" || bad "sandbox override missing or wrong: $(head -c 600 "$T/check-ov.json")"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ" > "$T/check-ov.txt" || true
grep -q 'warn: sandbox override: .*settings.local.json:4 sets sandbox.enabled=false' "$T/check-ov.txt" && ok "text mode prints the override warning" || bad "text mode has no override warning"

# 9b. control: no project settings at all, user scope true: no override
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-noov.json" || true
grep -q '"sandbox_override": null' "$T/check-noov.json" && ok "no project settings: sandbox_override null" || bad "false positive override with no project settings"

# 9c. control: project false but user scope unset: nothing is overridden
H3="$T/home-unset"; mkdir -p "$H3/.claude"; printf '{}\n' > "$H3/.claude/settings.json"
ORK_SETTINGS_HOME="$H3" bash "$CHECKER" "$PJ" --json > "$T/check-unset.json" || true
grep -q '"sandbox_override": null' "$T/check-unset.json" && ok "project false with user unset: no override reported" || bad "override reported with nothing to override"

# 9d. control: project true over user true: no override
PJ2="$T/proj-true"; mkdir -p "$PJ2/.claude"; printf '{\n  "sandbox": {\n    "enabled": true\n  }\n}\n' > "$PJ2/.claude/settings.json"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ2" --json > "$T/check-both.json" || true
grep -q '"sandbox_override": null' "$T/check-both.json" && ok "project true over user true: no override" || bad "override reported when both scopes agree"

# The unattended checks also read the process env, so every run below strips
# the variables it asserts on: a lane that exports them must not flip a test.
UNSET_ENV=(env -u CLAUDE_CODE_RETRY_WATCHDOG -u CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS
  -u CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS -u CLAUDE_CODE_RETRY_WATCHDOG_USAGE_LIMIT_RECHECK_MS
  -u CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS)
# run_chk <home> <out> <json|text> [VAR=value ...]: these homes carry no deny payload,
# so the checker must exit 1; any other code is a crash and fails the test.
run_chk() {
  local home="$1" out="$2" mode="$3" rc=0; shift 3
  if [ "$mode" = json ]; then
    "${UNSET_ENV[@]}" ORK_SETTINGS_HOME="$home" "$@" bash "$CHECKER" "$T/no-such-project" --json > "$out" || rc=$?
  else
    "${UNSET_ENV[@]}" ORK_SETTINGS_HOME="$home" "$@" bash "$CHECKER" "$T/no-such-project" > "$out" || rc=$?
  fi
  [ "$rc" -eq 1 ] || bad "checker exited $rc for $home (want 1, no deny payload)"
}

# 10. CC 2.1.299 idle compaction: idleCompaction:false is named with its file, never failed on.
H4="$T/home-idle"; mkdir -p "$H4/.claude"
printf '{\n  "idleCompaction": false,\n  "env": { "CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS": "400000" }\n}\n' > "$H4/.claude/settings.json"
run_chk "$H4" "$T/check-idle.json" json
node -e '
const o=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")); const i=o.unattended && o.unattended.idle_compaction;
const {normalize}=require("node:path"); const f=normalize(process.argv[2]);
const ok = i && i.setting==="false" && i.source===f && i.min_tokens==="400000" && i.min_tokens_source===f && /idleCompaction is false/.test(i.warning||"");
process.exit(ok?0:1)' "$T/check-idle.json" "$H4/.claude/settings.json" \
  && ok "idleCompaction:false reported with its file and a warning" || bad "idle compaction posture wrong: $(head -c 600 "$T/check-idle.json")"
run_chk "$H4" "$T/check-idle.txt" text
grep -q 'warn: idleCompaction is false' "$T/check-idle.txt" && ok "text mode prints the idle compaction warning" || bad "text mode has no idle compaction warning"

# 10b. control: key unset means CC's default (on), no warning
run_chk "$H3" "$T/check-idle-unset.json" json
node -e '
const i=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.idle_compaction;
process.exit(i.setting==="unset" && i.warning===null && i.min_tokens===null ? 0 : 1)' "$T/check-idle-unset.json" \
  && ok "idleCompaction unset: no warning" || bad "idle compaction warned with the key unset"

# 11. CC 2.1.301 and 2.1.305: watchdog on without the usage-limit variables gets one offer per variable.
H5="$T/home-wd"; mkdir -p "$H5/.claude"
printf '{\n  "env": { "CLAUDE_CODE_RETRY_WATCHDOG": "1" }\n}\n' > "$H5/.claude/settings.json"
run_chk "$H5" "$T/check-wd.json" json
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
const vars=w.offers.map((x)=>x.variable);
const ok = w.enabled===true && vars.includes("CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS")
  && vars.includes("CLAUDE_CODE_RETRY_WATCHDOG_USAGE_LIMIT_RECHECK_MS") && vars.includes("CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS");
process.exit(ok?0:1)' "$T/check-wd.json" \
  && ok "watchdog on: offers the usage-limit wait, recheck and wait caps" || bad "watchdog offers missing: $(head -c 600 "$T/check-wd.json")"

# 11b. the same variables from the process env (how a lane launcher sets them) close the offers
run_chk "$H5" "$T/check-wd-set.json" json CLAUDE_CODE_RETRY_WATCHDOG_MAX_USAGE_LIMIT_WAIT_MS=900000 \
  CLAUDE_CODE_RETRY_WATCHDOG_USAGE_LIMIT_RECHECK_MS=300000 CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS=1800000
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
process.exit(w.offers.length===0 && w.max_usage_limit_wait_ms==="900000" && w.usage_limit_recheck_ms==="300000" ? 0 : 1)' "$T/check-wd-set.json" \
  && ok "watchdog with all caps set: no offers" || bad "offers left with the caps set: $(head -c 600 "$T/check-wd-set.json")"

# 11c. control: watchdog off means no offers at all
run_chk "$H3" "$T/check-wd-off.json" json
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
process.exit(w.enabled===false && w.offers.length===0 ? 0 : 1)' "$T/check-wd-off.json" \
  && ok "watchdog off: no offers" || bad "offers made with the watchdog off"

# 12. Precedence (CC 2.1.281): the launch environment wins over settings `env` when both set a variable.
# 12a. a conflicting minimum: settings say 400000, the launch env says 200000
run_chk "$H4" "$T/check-prec-min.json" json CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS=200000
node -e '
const i=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.idle_compaction;
process.exit(i.min_tokens==="200000" && i.min_tokens_source==="environment" ? 0 : 1)' "$T/check-prec-min.json" \
  && ok "launch env min tokens wins over settings env" || bad "settings env won the min tokens conflict: $(head -c 600 "$T/check-prec-min.json")"
# 12b. the switch, launch off over settings on: settings say 1, the launch env says 0
run_chk "$H5" "$T/check-prec-off.json" json CLAUDE_CODE_RETRY_WATCHDOG=0
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
process.exit(w.enabled===false && w.source==="environment" && w.offers.length===0 ? 0 : 1)' "$T/check-prec-off.json" \
  && ok "launch env watchdog=0 wins over settings watchdog=1" || bad "settings env won the watchdog-off conflict: $(head -c 600 "$T/check-prec-off.json")"
# 12c. the switch, launch on over settings off: settings say 0, the launch env says 1
H6="$T/home-wd-off"; mkdir -p "$H6/.claude"
printf '{\n  "env": { "CLAUDE_CODE_RETRY_WATCHDOG": "0" }\n}\n' > "$H6/.claude/settings.json"
run_chk "$H6" "$T/check-prec-on.json" json CLAUDE_CODE_RETRY_WATCHDOG=1
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
process.exit(w.enabled===true && w.source==="environment" ? 0 : 1)' "$T/check-prec-on.json" \
  && ok "launch env watchdog=1 wins over settings watchdog=0" || bad "settings env won the watchdog-on conflict: $(head -c 600 "$T/check-prec-on.json")"
# 12d. a conflicting cap: settings say 600000, the launch env says 1800000
H7="$T/home-wd-cap"; mkdir -p "$H7/.claude"
printf '{\n  "env": { "CLAUDE_CODE_RETRY_WATCHDOG": "1", "CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS": "600000" }\n}\n' > "$H7/.claude/settings.json"
run_chk "$H7" "$T/check-prec-cap.json" json CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS=1800000
node -e '
const w=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).unattended.retry_watchdog;
process.exit(w.max_wait_ms==="1800000" ? 0 : 1)' "$T/check-prec-cap.json" \
  && ok "launch env cap wins over settings env cap" || bad "settings env won the cap conflict: $(head -c 600 "$T/check-prec-cap.json")"

echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
